            if (UkuwayConfig.get().isHideCosmetics()) {
                entity.equipStack(slot, ItemStack.EMPTY);
            }
        } else if (!UkuwayConfig.get().isHideCosmetics() && oldHeadStack != null) {
            entity.equipStack(slot, oldHeadStack);
        }
    }
}


